/* Optional route-scoped first-party preference. No SDK, attribution or contact fields. */
(function () {
  'use strict';
  const config = window.BSREGoogleConfig || {};
  const path = '/off-plan-dubai-de-de/';
  const pendingCookie = '__Host-bsre_de_offplan_ads_pending';
  if (config.country_path !== path || location.pathname !== path || config.enabled !== true) return;
  let endpoint, privacy;
  try {
    endpoint = new URL(config.choice_endpoint);
    privacy = new URL(config.country_privacy_url);
    if (endpoint.origin !== location.origin || endpoint.pathname !== '/wp-json/bsre/v1/offplan-country/off-plan-dubai-de-de/ad-choice'
        || privacy.origin !== location.origin || privacy.pathname !== '/property-enquiry-privacy-notice/'
        || endpoint.search || endpoint.hash || privacy.search || privacy.hash) return;
  } catch (_) { return; }

  const denied = Object.freeze({ analytics:false, ad_measurement:false, personalization:false });
  const unknown = Object.freeze({ known:false, acknowledged:false, measurement_eligible:false, preferences:denied,
    decision_version:'none', notice_version:config.country_notice_version, preference_expires_at:0, preference_days:180 });
  let snapshot = unknown, pending = false;
  let peerRevision = 0, peerInvalidated = false;
  let choices;
  try { choices = new BroadcastChannel('bsre-de-offplan-ads-choice'); } catch (_) { /* Server checks and the pending cookie remain active. */ }

  function normalizeSnapshot(value) {
    if (!value || value.notice_version !== config.country_notice_version || value.known !== true || value.acknowledged !== true
        || !/^[a-f0-9]{32}$/.test(value.decision_version || '') || value.preferences?.analytics !== false
        || value.preferences.personalization !== false || typeof value.preferences.ad_measurement !== 'boolean'
        || value.preferences.ad_measurement !== value.measurement_eligible || value.preference_days !== 180
        || !Number.isInteger(value.preference_expires_at) || value.preference_expires_at <= Math.floor(Date.now()/1000)) return null;
    return Object.freeze({...value, preferences:Object.freeze({...value.preferences})});
  }
  function choicePending() {
    return document.cookie.split(';').some(item => item.trim() === pendingCookie+'=1');
  }
  function allowed() {
    try {
      return !pending && !peerInvalidated && snapshot.measurement_eligible
        && snapshot.preference_expires_at > Math.floor(Date.now()/1000) && !choicePending();
    } catch (_) { return false; }
  }
  function publish(value) {
    snapshot = normalizeSnapshot(value) || unknown;
    window.BSRELeadConfig.measurementEligible = allowed() === true;
    window.dispatchEvent(new CustomEvent('bsre:consent-changed',{detail:{refused:{analytics:true,advertising:!allowed()}}}));
  }
  function retireAdvertising() {
    window.dispatchEvent(new CustomEvent('bsre:consent-will-change',{detail:{analytics:false,advertising:false}}));
    publish(null);
  }
  choices?.addEventListener('message', event => {
    if (event.data !== 'invalidate') return;
    ++peerRevision;
    peerInvalidated = true;
    retireAdvertising();
  });
  window.BSREConsentBridge = Object.freeze({ normalizeSnapshot, getSnapshot:() => snapshot,
    permissions:() => ({analytics:false, advertising:allowed() === true}), measurementEligible:() => allowed() === true });
  window.addEventListener('bsre:transport-ready', event => {
    if (!pending && !peerInvalidated) publish(event.detail?.countryMeasurement);
  });

  const box = document.createElement('aside');
  box.id = 'bsre-country-ads-choice';
  box.className = 'bsre-consent-panel';
  const title = document.createElement('h2');
  title.textContent = 'Optionale Anzeigenmessung';
  const detail = document.createElement('p');
  detail.textContent = 'Nur mit Ihrer Zustimmung messen wir auf dieser Anfrageseite, ob eine akzeptierte Immobilienanfrage auf unsere Google-Anzeigen zurückgeht. Dazu werden die Seitenadresse ohne Suchparameter und eine zufällige Anfragereferenz verwendet. Sie können den Dienst auch ohne diese Messung nutzen und Ihre Wahl hier widerrufen. ';
  const note = document.createElement('a');
  note.href = privacy.href;
  note.hreflang = 'en';
  note.textContent = 'Datenschutzhinweise (Englisch)';
  detail.appendChild(note);
  const accept = document.createElement('button');
  const reject = document.createElement('button');
  accept.type = reject.type = 'button';
  accept.textContent = 'Anzeigenmessung erlauben';
  reject.textContent = 'Ablehnen oder widerrufen';
  const status = document.createElement('p');
  status.setAttribute('role','status');
  box.append(title,detail,accept,reject,status);
  document.querySelector('main')?.appendChild(box);
  function markPending() {
    document.cookie = pendingCookie+'=1; Max-Age=7200; Path=/; Secure; SameSite=Strict';
    return choicePending();
  }
  async function save(grant) {
    if (pending || !window.BSRELeadConfig.csrfToken) return;
    pending = true;
    const startRevision = peerRevision;
    retireAdvertising();
    accept.disabled = reject.disabled = true;
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), 10000);
    let next;
    try {
      if (!markPending()) throw new Error('Choice could not be marked pending');
      // A sibling can stop immediately while the first-party POST is pending.
      // The signal carries no choice, subject, receipt, or advertising ID.
      try { choices?.postMessage('invalidate'); } catch (_) { /* Fall back to pending cookie and lease checks. */ }
      const response = await fetch(endpoint.href,{method:'POST',credentials:'same-origin',cache:'no-store',signal:controller.signal,
        headers:{'Content-Type':'application/json','X-BSRE-CSRF':window.BSRELeadConfig.csrfToken},
        body:JSON.stringify({ad_measurement:grant,notice_version:config.country_notice_version})});
      next = await response.json();
      if (!response.ok || next.ok !== true || !normalizeSnapshot(next)) throw new Error('Choice could not be confirmed');
      if (peerRevision !== startRevision || choicePending()) throw new Error('Choice changed while pending');
      peerInvalidated = false;
      status.textContent = grant ? 'Anzeigenmessung erlaubt.' : 'Anzeigenmessung abgelehnt.';
    } catch (_) {
      next = null;
      status.textContent = 'Ihre Wahl wurde nicht bestätigt. Auf dieser Seite bleibt die Anzeigenmessung deaktiviert.';
    } finally {
      window.clearTimeout(timer);
      pending = false;
      accept.disabled = reject.disabled = false;
      publish(next);
    }
  }
  accept.addEventListener('click', event => { if (event.isTrusted) void save(true); });
  reject.addEventListener('click', event => { if (event.isTrusted) void save(false); });
}());

if (country) {
  if (purpose !== 'advertising') return false;
  payload = {...payload, page_path:country};
}

let config;
try { config = JSON.parse(document.getElementById('bsre-runtime-config').textContent); } catch (_) { return; }
const country = config?.country_path === '/off-plan-dubai-de-de/' ? config.country_path : '';
if (config?.country_path !== undefined && (!country || config.purpose !== 'advertising')) return;

$alias = $alias_id ? offplan_country_ad_state($country)['snapshot'] : null;
if ($alias_id ? !$alias['measurement_eligible'] : !measurement_runtime_permission($params['purpose'], $repository)) return $deny();
$session = $alias_id ? offplan_country_ad_session() : ($_COOKIE[CONSENT_SESSION_COOKIE] ?? '');
$binding = $alias_id ? $country . '|' . $alias_id : 'off-plan';
$decision = $alias_id ? $alias['decision_version'] : measurement_runtime_revision($repository);
if ($alias_id) {
    $config['country_path'] = $country;
    $config['cookie_prefix'] = 'bsre_enq_de_offplan_ads';
    $config['status_endpoint'] = offplan_country_ad_endpoint($country, 'ad-status');
    if ($config['status_endpoint'] === '') return $deny();
}
try { $config['lease_token'] = measurement_lease_token($params['purpose'], is_string($session) ? $session : '', $config['config_version'], time(), $decision, $binding); $config['lease_seconds'] = 30; }

$id = offplan_country_native_page($path);
$ad_key = offplan_country_ad_marker($path, $id, $payload->request_id);
$choice = offplan_country_ad_state($path);
$retry = consent_request_is_retry($request);
$release = !$retry && $choice['snapshot']['measurement_eligible'] && measurement_eligible($raw)
    && hash_equals($choice['snapshot']['decision_version'], $decision);
$capture = $release ? offplan_country_ad_stage($raw, $payload, $choice, $ad_key)
    : consent_stage_submission($raw, $retry, null, null, $key);
if ($release && !$capture['recorded'] && !$capture['conflict']) {
    $release = false;
    $capture = consent_stage_submission($raw, $retry, null, null, $key);
}

if (hash_equals($ad_key, (string) ($row['decision_version'] ?? '')) && $row['notice_version'] === OFFPLAN_COUNTRY_AD_NOTICE) {
    return relay_accepted_enquiry($raw, $capture, false,
        static fn ($stored, $receipt, $body) => offplan_country_ad_link($stored, $receipt, $body, $path, $release));
}
